import sqlite3

def insert_contact(email, phone):
    conn = sqlite3.connect('contacts.db')
    cursor = conn.cursor()
    if email is None:
        email_sql = 'NULL'
    else:
        email_sql = "'" + email + "'"
    if phone is None:
        phone_sql = 'NULL'
    else:
        phone_sql = "'" + phone + "'"
    cursor.execute('INSERT INTO contacts (email, phone) VALUES (' + email_sql + ', ' + phone_sql + ')')
    conn.commit()
    conn.close()

insert_contact(None, '555-0100')

import sqlite3
from contextlib import contextmanager

@contextmanager
def db_connection(db_path):
    conn = sqlite3.connect(db_path)
    try:
        yield conn
    except Exception:
        conn.rollback()
        raise
    else:
        conn.commit()
    finally:
        conn.close()

def query_db(db_path, sql, params=None):
    with db_connection(db_path) as conn:
        cursor = conn.cursor()
        if params:
            cursor.execute(sql, params)
        else:
            cursor.execute(sql)
        return cursor.fetchall()

def insert_db(db_path, sql, params=None):
    with db_connection(db_path) as conn:
        cursor = conn.cursor()
        if params:
            cursor.execute(sql, params)
        else:
            cursor.execute(sql)

# Example usage
query_db('shop.db', "SELECT * FROM products WHERE price > ?", (100,))
insert_db('shop.db', "INSERT INTO orders (item) VALUES (?)", ('book',))

